from .core import *

def make(family,v,n):
    q=2+v;A=[q,q+1,q+2];B=[q+2,q+3];union=sorted(set(A)|set(B));common=sorted(set(A)&set(B));fmt=lambda a:'{'+', '.join(map(str,a))+'}'
    vm={'type':'venn','a':A,'b':B}
    if family in ['sets_intro','sets_symbols','subset','sets_relations','union_intro','union_build']:
        tasks=[number(f'Сколько элементов в A = {fmt(A)}?',3,'Каждый различный элемент учитывается один раз.'),choice(f'{q} принадлежит A = {fmt(A)}?','Да',['Да','Нет'],'Элемент принадлежит множеству, если входит в его список.'),choice('Множество натуральных чисел между 2 и 3 — …','Пустое множество',['Пустое множество','{2, 3}','{0}'],'Натуральных чисел строго между соседними числами нет.'),multi(f'A = {fmt(A)}, B = {fmt(B)}. Выбери все общие элементы.',common,union,'Пересечение A ∩ B содержит общие элементы.'),multi(f'Собери A ∪ B для A = {fmt(A)}, B = {fmt(B)}.',union,union+[q+5],'В объединение входят элементы хотя бы одного из множеств.'),choice(f'Является ли {fmt([q,q+1])} подмножеством {fmt(A)}?','Да',['Да','Нет'],'Каждый элемент подмножества должен входить в исходное множество.')]
        if family=='sets_symbols':
            tasks[0]=choice(f'Как записать: {q} входит в A = {fmt(A)}?',f'{q} ∈ A',[f'{q} ∈ A',f'{q} ∉ A','A = ∅'],'Знак ∈ означает «принадлежит».')
            tasks[2]=choice('Как обозначается пустое множество?','∅',['∅','∩','∪'],'Пустое множество не содержит элементов.')
        if family=='subset':
            tasks[0]=choice(f'C = {fmt([q,q+1])}, A = {fmt(A)}. Какая запись верна?','C ⊂ A',['C ⊂ A','A ⊂ C','C = A'],'Все элементы C есть в A, но в A есть ещё элемент.')
            tasks[4]=choice(f'C = {fmt([q,q+5])}. Является ли C подмножеством A = {fmt(A)}?','Нет',['Да','Нет'],f'Проверь, есть ли элемент {q+5} в A.')
        if family=='sets_relations':
            tasks[0]=choice(f'A = {fmt(A)}, B = {fmt(B)}. Множества пересекаются?','Да',['Да','Нет'],'Достаточно хотя бы одного общего элемента.',model=vm)
            tasks[2]=choice('Множества чётных и нечётных натуральных чисел пересекаются?','Нет',['Да','Нет'],'Число не может быть одновременно чётным и нечётным.')
        if family.startswith('union'):
            tasks[0]=choice('Пересечение A ∩ B содержит…','Только общие элементы',['Все элементы двух множеств','Только общие элементы','Только элементы A вне B'],'Общая область диаграммы соответствует пересечению.',model=vm)
            tasks[1]=choice('Элемент есть в A и B. В A ∪ B его записывают…','Один раз',['Один раз','Два раза','Не записывают'],'Множество не содержит повторяющихся элементов.')
        return package('Клубы и коллекции',['Множество — совокупность элементов. Записываем элементы в фигурных скобках без повторений.','∈ — принадлежит, ∉ — не принадлежит, ∅ — пустое множество.','A ∩ B — общие элементы. A ∪ B — элементы хотя бы одного множества.','C ⊂ A: каждый элемент C входит в A; в наших примерах C отличается от A.'],['A = {1, 2, 3}, B = {3, 4}','A ∩ B = {3}; A ∪ B = {1, 2, 3, 4}. Элемент 3 в объединении пишем один раз.'],'Придумай два множества школьных принадлежностей. Изобрази их кругами, запиши объединение и пересечение.',tasks)
    if family=='venn_words':
        left=5+v;both=2+v%3;right=4+v;outside=3;total=left+right+both+outside
        model={'type':'vennCounts','left':left,'both':both,'right':right,'outside':outside,'labels':['Робототехника','Домбыра']}
        tasks=[number('Сколько учеников посещают оба кружка?',both,'Общая часть кругов — участники двух кружков.',model=model),number('Сколько посещают только робототехнику?',left,'Это левая область вне пересечения.',model=model),number(f'Робототехника: {left+both}, домбыра: {right+both}, оба: {both}. Сколько посещают хотя бы один кружок?',left+right+both,'Сложи количества и вычти повторно учтённых участников двух кружков.'),number(f'В группе {total} учеников, хотя бы один кружок посещают {left+right+both}. Сколько не посещают ни один?',outside,'Вычти объединение из общего числа.'),choice('Почему участников обоих кружков вычитают один раз при сложении численностей?','Их посчитали дважды',['Они не входят ни в один кружок','Их посчитали дважды','Они посещают третий кружок'],'Ученик должен учитываться в объединении один раз.'),number(f'В спортивном кружке {8+v}, в шахматном {7+v}, в обоих 3. Сколько всего разных участников?',12+2*v,'Нарисуй два пересекающихся круга.')]
        return package('Посчитай участников без повторов',['Начинай заполнение диаграммы с общей части.','Чтобы найти тех, кто только в одном множестве, вычти общую часть из численности этого множества.','Для объединения сложи численности и вычти пересечение один раз.'],['12 занимаются спортом, 8 шахматами, 3 — обоими','Всего разных участников: 12 + 8 − 3 = 17. Данные учебные.'],'Составь задачу о двух кружках. Покажи на диаграмме тех, кто в обоих, только в одном и ни в одном.',tasks)
    if family=='percent_intro':
        p=10*(1+v%8)
        tasks=[choice('Какой процент сотенной таблицы закрашен?',str(p)+'%',[str(p)+'%',str(p//10)+'%',str(100-p)+'%'],'В таблице 100 равных клеток. Одна клетка — 1%.',model=fraction(p,100)),number('Один процент — какая дробь целого?',F(1,100),'Процент — одна сотая часть.'),number(f'Переведи {p}% в дробь.',F(p,100),'Раздели процентное число на 100.'),number(f'{p}/100 — это сколько процентов?',p,'Сколько сотых, столько и процентов.'),number('Переведи 1/2 в проценты.',50,'1/2 = 50/100.'),number(f'Доля равна {dec(F(p,100))}. Сколько это процентов?',p,'Умножь долю на 100.')]
        return package('Сотня маленьких частей',['1% = 1/100 = 0,01. Всё целое — 100%.','Проценты в дробь: раздели на 100. Дробь в проценты: умножь на 100.'],['3/4 = 75%','3/4 = 75/100. Значит, это 75 частей из ста.'],'Нарисуй сетку 10 × 10. Покажи 25%, 50% и 75% на трёх копиях.',tasks)
    if family=='percent_part':
        total=200+100*v;p=10*(1+v%4)
        tasks=[number(f'Найди 1% от {total}.',F(total,100),'Раздели целое на 100.'),number(f'Найди 10% от {total}.',F(total,10),'Десять процентов — десятая часть.'),number(f'Найди {p}% от {total}.',F(total*p,100),'Найди один процент и умножь на '+str(p)+'.'),number(f'В библиотеке {total} новых книг. 25% — сказки. Сколько сказок?',F(total,4),'25% = 1/4.'),choice('При нахождении 20% от 300 выбираем…','300 × 20 / 100',['300 / 20','300 × 20 / 100','300 + 20'],'Нужна доля заданного целого.'),number(f'План акции — {total} кг бумаги. Собрали 50%. Сколько осталось до плана?',total//2,'Осталось 100% − 50% = 50%.')]
        return package('Найди процентную долю',['Найди 1%: раздели число на 100. Затем умножь на нужное число процентов.','Проверь: доля меньше 100% должна быть меньше положительного целого.'],['15% от 200','200 ÷ 100 × 15 = 30.'],'Составь задачу о школьной акции на нахождение 10% и 25% от одного числа.',tasks)
    if family=='percent_ratio':
        a=10+5*v;b=2*a
        tasks=[number(f'{a} из {b} — какая дробь?',F(1,2),'Раздели сравниваемую часть на выбранное целое.'),number(f'Сколько процентов составляет {a} от {b}?',50,'Долю умножь на 100%.'),number(f'Сколько процентов составляет {b} от {a}?',200,'Теперь за 100% принято меньшее число. Результат может быть больше 100%.'),choice('При изменении числа, принятого за 100%, процентное отношение…','Меняется',['Не меняется','Меняется'],'Всегда называй основание сравнения.'),number(f'Из {4*a} заданий решено {a}. Сколько процентов решено?',25,'Одна четверть — 25%.'),number(f'Сколько процентов составляет {3*a} от {a}?',300,'Числитель в три раза больше основания сравнения.')]
        return package('Что принято за сто процентов?',['Процентное отношение a к b: a ÷ b × 100%. Число b принимают за 100%.','Обратное отношение обычно даёт другой результат. Оно может быть больше 100%.'],['10 от 20 и 20 от 10','10 ÷ 20 × 100% = 50%; 20 ÷ 10 × 100% = 200%.'],'Сравни числа 15 и 30 в обоих направлениях. Подпиши, что каждый раз принято за 100%.',tasks)
    if family=='percent_whole':
        whole=200+100*v
        tasks=[number(f'10% числа равны {whole//10}. Найди 1%.',whole//100,'Известную долю раздели на количество процентов.'),number(f'10% числа равны {whole//10}. Найди всё число.',whole,'После нахождения 1% умножь на 100.'),number(f'25% числа равны {whole//4}. Найди число.',whole,'25% — четверть; целое в 4 раза больше.'),choice('20% числа равны 30. Как найти число?','30 ÷ 20 × 100',['30 × 20 ÷ 100','30 ÷ 20 × 100','30 + 20'],'Сначала найди один процент.'),number(f'Половина фонда библиотеки — {whole//2} книг. Сколько книг в фонде?',whole,'50% — половина.'),number(f'Выполнено 40% плана, это {whole*2//5} деталей. Каков весь план?',whole,'Проверь, найдя 40% от полученного числа.')]
        return package('Восстанови целое',['Если p% числа равны a, то всё число: a ÷ p × 100.','Проверяй обратной задачей: найди p% от результата.'],['20% числа равны 30','1% = 30 ÷ 20 = 1,5; 100% = 150. Проверка: 20% от 150 равны 30.'],'Составь пару обратных задач: найти 25% числа и найти число по его 25%.',tasks)
    if family=='percent_words':
        price=1000+200*v;discount=price//5;count=20+4*v
        tasks=[number(f'Учебная цена рюкзака {price} ₸. Скидка 10%. Сколько тенге скидка?',price//10,'Пока найди только размер скидки.'),number(f'Цена {price} ₸, скидка 20%. Сколько заплатят?',price-discount,'Вычти скидку из начальной цены.'),number(f'В кружке {count} детей. 25% участвуют в выставке. Сколько участников?',count//4,'Четверть числа — это 25%.'),number(f'Собрали {count//2} кг бумаги из плана {count} кг. Сколько процентов плана выполнено?',50,'Сравни собранное с планом.'),number('Устройство полностью заряжено. Использовано 20% заряда. Сколько процентов осталось?',80,'Полный заряд — 100%. Вычти использованную долю.'),number(f'После скидки 50% вещь стоит {price//2} ₸. Какова исходная цена?',price,'Известна половина исходной цены. Данные учебные.')]
        return package('Проверь предложение',['Уточни вопрос: нужна сама скидка, новая цена, доля выполнения или исходное число.','Всегда определяй, какое число принято за 100%.','Цены в заданиях условные и нужны только для вычислений.'],['Цена 2000 ₸, скидка 10%','Скидка 200 ₸. Новая цена: 2000 − 200 = 1800 ₸.'],'Придумай ценник со скидкой 10% или 25%. Отдельно запиши исходную цену, скидку в тенге и новую цену.',tasks)
    raise ValueError(family)
